    {"id": "jennifer-dulos-2019", "name": "Jennifer Dulos", "type": "Homicide", "status": "Solved", "year": 2019, "date": "May 24, 2019", "state": "Connecticut", "city": "New Canaan", "age": 50, "gender": "Female", "summary": "Jennifer Dulos, a mother of five, vanished during a contentious divorce. Her estranged husband Fotis Dulos was charged with murder but died by suicide before trial. Her body was never found.", "lastSeen": "May 24, 2019, New Canaan, Fairfield County, Connecticut", "tags": ["homicide", "Connecticut", "2010s", "solved"], "sources": [{"title": "Disappearance of Jennifer Dulos - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Jennifer_Dulos"}, {"title": "Dulos case - Hartford Courant", "url": "https://www.courant.com/news/connecticut/jennifer-dulos/"}, {"title": "Fotis Dulos death - NBC News", "url": "https://www.nbcnews.com/news/us-news/fotis-dulos-jennifer-dulos/"}], "narrative": ["Jennifer Dulos, 50, a mother of five, disappeared on May 24, 2019 in New Canaan, Connecticut. She was last seen dropping her children at school during a contentious divorce and custody battle.", "Surveillance footage showed her estranged husband Fotis Dulos and his girlfriend Michelle Troconis discarding garbage bags containing Jennifer's blood-stained clothing along a Hartford street.", "Fotis was arrested and charged with murder. He maintained his innocence but died by suicide on January 30, 2020, two days after a bond hearing.", "Troconis was convicted of conspiracy to commit murder in 2024. Jennifer's body has never been found. The case highlighted dangers women face during divorce proceedings."], "timeline": [{"date": "2019-05-24", "event": "Jennifer Dulos disappears."}, {"date": "2020-01-30", "event": "Fotis Dulos dies by suicide."}, {"date": "2024-03-01", "event": "Troconis convicted of conspiracy."}], "enriched": True},
    {"id": "kristin-smart-1996", "name": "Kristin Smart", "type": "Missing Person/Homicide", "status": "Solved", "year": 1996, "date": "May 25, 1996", "state": "California", "city": "San Luis Obispo", "age": 19, "gender": "Female", "summary": "Cal Poly student Kristin Smart vanished in 1996 after a party. Paul Flores, who walked her home, was convicted of murder in 2022 after the 'Your Own Backyard' podcast revived the case.", "lastSeen": "May 25, 1996, Cal Poly San Luis Obispo campus, California", "tags": ["missing person", "homicide", "California", "1990s", "podcast", "solved"], "sources": [{"title": "Disappearance of Kristin Smart - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Kristin_Smart"}, {"title": "Smart case - San Luis Obispo Tribune", "url": "https://www.sanluisobispo.com/news/kristin-smart/"}, {"title": "Flores conviction - CNN", "url": "https://www.cnn.com/2022/10/18/us/kristin-smart-paul-flores-verdict/index.html"}], "narrative": ["On May 25, 1996, Kristin Smart, a 19-year-old Cal Poly San Luis Obispo freshman, disappeared after an off-campus party. Fellow student Paul Flores was the last person seen with her.", "Despite years of investigation, no charges were filed. The case was revived by Chris Lambert's podcast 'Your Own Backyard,' which began in 2019 and attracted millions of listeners.", "In 2021, Flores was arrested for murder and his father Ruben was charged as an accessory for allegedly helping hide the body. Cadaver dogs hit on a spot under the deck of Ruben's home.", "Paul Flores was convicted of first-degree murder in October 2022. Ruben was acquitted. Kristin's body has never been found."], "timeline": [{"date": "1996-05-25", "event": "Kristin Smart vanishes."}, {"date": "2022-10-18", "event": "Paul Flores convicted of first-degree murder."}], "enriched": True},
    {"id": "natalee-holloway-suspect-2023", "name": "Natalee Holloway (confession)", "type": "Missing Person", "status": "Solved", "year": 2023, "date": "October 18, 2023", "state": "Alabama", "city": "Birmingham", "age": 18, "gender": "Female", "summary": "Joran van der Sloot was extradited from Peru and pleaded guilty to extorting Natalee Holloway's family. He admitted for the first time that he killed Natalee in Aruba in 2005.", "lastSeen": "May 30, 2005, Aruba", "tags": ["missing person", "Alabama", "2020s", "solved"], "sources": [{"title": "Natalee Holloway case resolution - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Natalee_Holloway"}, {"title": "Van der Sloot guilty plea - CNN", "url": "https://www.cnn.com/2023/10/18/us/joran-van-der-sloot-natalee-holloway-plea/index.html"}, {"title": "Van der Sloot extradition - NBC", "url": "https://www.nbcnews.com/news/us-news/joran-van-der-sloot-natalee-holloway/"}], "narrative": ["In October 2023, Joran van der Sloot was temporarily extradited from Peru, where he was serving a 28-year sentence for murdering Stephany Flores, to face charges in the United States.", "Van der Sloot pleaded guilty to extortion and wire fraud for taking $25,000 from Natalee Holloway's mother Beth in 2010 in exchange for information about Natalee's remains—information that turned out to be false.", "During the plea hearing, van der Sloot admitted for the first time that he killed Natalee Holloway on a beach in Aruba on May 30, 2005, and disposed of her body in the ocean.", "He was sentenced to 20 years in U.S. federal prison, to be served after his Peruvian sentence. Beth Holloway finally received the closure she had sought for 18 years."], "timeline": [{"date": "2005-05-30", "event": "Natalee Holloway disappears in Aruba."}, {"date": "2023-10-18", "event": "Van der Sloot confesses to killing Natalee."}], "enriched": True},
    {"id": "suzanne-morphew-2020", "name": "Suzanne Morphew", "type": "Missing Person", "status": "Unsolved", "year": 2020, "date": "May 10, 2020", "state": "Colorado", "city": "Maysville", "age": 49, "gender": "Female", "summary": "Suzanne Morphew disappeared on Mother's Day 2020 while biking near Maysville, Colorado. Her husband Barry was charged with murder but charges were dropped. Her remains were found in 2023.", "lastSeen": "May 10, 2020, near Maysville, Chaffee County, Colorado", "tags": ["missing person", "Colorado", "2020s", "unsolved"], "sources": [{"title": "Disappearance of Suzanne Morphew - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Suzanne_Morphew"}, {"title": "Morphew case - Denver Post", "url": "https://www.denverpost.com/tag/suzanne-morphew/"}, {"title": "Remains found - CBS Denver", "url": "https://www.cbsnews.com/colorado/news/suzanne-morphew-remains-found/"}], "narrative": ["Suzanne Morphew, 49, disappeared on Mother's Day, May 10, 2020, while reportedly on a bike ride near her home in Maysville, Colorado. Her husband Barry reported her missing.", "Barry Morphew was arrested and charged with first-degree murder in 2021. However, prosecutors dropped the charges in 2022 before trial, citing concerns about evidence.", "In September 2023, Suzanne's remains were found in a remote area of Chaffee County. The discovery reignited calls for renewed charges.", "As of 2024, Barry Morphew has not been recharged. The case remains technically unsolved, though he remains the primary person of interest."], "timeline": [{"date": "2020-05-10", "event": "Suzanne Morphew disappears."}, {"date": "2023-09-22", "event": "Her remains found in Chaffee County."}], "enriched": True},
    {"id": "sarah-everard-2021", "name": "Sarah Everard", "type": "Homicide", "status": "Solved", "year": 2021, "date": "March 3, 2021", "state": "United Kingdom", "city": "London", "country": "United Kingdom", "age": 33, "gender": "Female", "summary": "Sarah Everard was kidnapped, raped, and murdered by Metropolitan Police officer Wayne Couzens, who used his warrant card to conduct a fake arrest. The case triggered a national reckoning on women's safety.", "lastSeen": "March 3, 2021, Clapham Common area, London, England", "tags": ["homicide", "United Kingdom", "2020s", "solved"], "sources": [{"title": "Murder of Sarah Everard - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Sarah_Everard"}, {"title": "Everard case - BBC", "url": "https://www.bbc.com/news/uk-england-london-sarah-everard"}, {"title": "Couzens sentencing - The Guardian", "url": "https://www.theguardian.com/uk-news/sarah-everard"}], "narrative": ["On March 3, 2021, Sarah Everard, 33, disappeared while walking home from a friend's house in Clapham, south London. CCTV footage showed her being stopped by a man in a car.", "The man was Wayne Couzens, a serving Metropolitan Police officer. He used his warrant card and handcuffs to conduct a fake arrest, claiming Sarah had violated COVID lockdown rules.", "Couzens drove Sarah to Kent, where he raped and murdered her. Her remains were found a week later in woodland. The discovery triggered vigils and protests across the UK.", "Couzens was sentenced to a whole-life order—the most severe sentence in English law. The case exposed failures within the Met Police and led to reforms on vetting officers. Met Commissioner Cressida Dick resigned."], "timeline": [{"date": "2021-03-03", "event": "Sarah Everard kidnapped and murdered."}, {"date": "2021-09-30", "event": "Couzens sentenced to whole-life order."}], "enriched": True},
    {"id": "david-carrick-met-police-2023", "name": "David Carrick Victims", "type": "Serial Rape", "status": "Solved", "year": 2023, "date": "January 16, 2023", "state": "United Kingdom", "city": "London", "country": "United Kingdom", "age": None, "gender": "Female", "summary": "Metropolitan Police officer David Carrick pleaded guilty to 49 offenses including 24 rapes against 12 women over 17 years. He used his status as a police officer to prey on victims.", "lastSeen": "Various dates, Hertfordshire and London, England", "tags": ["serial rape", "United Kingdom", "2020s", "solved"], "sources": [{"title": "David Carrick case - BBC", "url": "https://www.bbc.com/news/uk-england-beds-bucks-herts-david-carrick"}, {"title": "Carrick sentencing - The Guardian", "url": "https://www.theguardian.com/uk-news/david-carrick"}, {"title": "Met Police failures - Sky News", "url": "https://news.sky.com/story/david-carrick-met-police/"}], "narrative": ["David Carrick, a Metropolitan Police officer for 20 years, pleaded guilty in January 2023 to 49 offenses including 24 rapes against 12 women committed between 2003 and 2020.", "Carrick used his position as a police officer to gain women's trust before controlling, manipulating, and sexually assaulting them. Some victims said they didn't report him because he was a police officer.", "He was sentenced to a minimum of 30 years in prison. The case, coming after the Sarah Everard murder, further damaged public trust in the Metropolitan Police.", "An internal review found that nine opportunities to investigate Carrick had been missed. The Met Police faced intense scrutiny over its vetting and complaints processes."], "timeline": [{"date": "2023-01-16", "event": "Carrick pleads guilty to 49 offenses."}, {"date": "2023-02-07", "event": "Sentenced to minimum 30 years."}], "enriched": True},
    {"id": "karen-read-2024", "name": "John O'Keefe (Karen Read)", "type": "Homicide", "status": "Unsolved", "year": 2022, "date": "January 29, 2022", "state": "Massachusetts", "city": "Canton", "age": 46, "gender": "Male", "summary": "Boston police officer John O'Keefe was found dead outside a home in Canton, Massachusetts. His girlfriend Karen Read was charged with murder. Her first trial ended in mistrial. Supporters claim she's being framed.", "lastSeen": "January 29, 2022, Canton, Norfolk County, Massachusetts", "tags": ["homicide", "Massachusetts", "2020s", "unsolved"], "sources": [{"title": "Karen Read case - Wikipedia", "url": "https://en.wikipedia.org/wiki/Death_of_John_O%27Keefe"}, {"title": "Read trial - Boston Globe", "url": "https://www.bostonglobe.com/metro/karen-read/"}, {"title": "Mistrial - CNN", "url": "https://www.cnn.com/2024/07/01/us/karen-read-mistrial/index.html"}], "narrative": ["On January 29, 2022, Boston police officer John O'Keefe, 46, was found dead in the snow outside a house in Canton, Massachusetts. He had injuries to his head and arm.", "His girlfriend Karen Read was charged with second-degree murder. Prosecutors alleged she struck O'Keefe with her SUV and left him to die in a snowstorm after a night of drinking.", "Read's defense argued she was being framed by law enforcement and that O'Keefe was killed inside the house during an altercation, then moved outside. The theory gained massive public support.", "Her first trial in 2024 ended in a mistrial after the jury deadlocked. The case has become one of the most divisive in Massachusetts legal history, with passionate supporters on both sides."], "timeline": [{"date": "2022-01-29", "event": "John O'Keefe found dead."}, {"date": "2024-07-01", "event": "Karen Read's first trial ends in mistrial."}], "enriched": True},
    {"id": "brian-walshe-2023", "name": "Ana Walshe", "type": "Homicide", "status": "Solved", "year": 2023, "date": "January 1, 2023", "state": "Massachusetts", "city": "Cohasset", "age": 39, "gender": "Female", "summary": "Ana Walshe, a Tishman Speyer executive, was reported missing from Cohasset, Massachusetts. Her husband Brian was charged with murder after police found evidence he dismembered her body.", "lastSeen": "January 1, 2023, their home in Cohasset, Norfolk County, Massachusetts", "tags": ["homicide", "Massachusetts", "2020s", "solved"], "sources": [{"title": "Disappearance of Ana Walshe - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Ana_Walshe"}, {"title": "Walshe case - Boston Globe", "url": "https://www.bostonglobe.com/metro/ana-walshe/"}, {"title": "Brian Walshe arrest - CNN", "url": "https://www.cnn.com/2023/01/ana-walshe-brian-walshe/index.html"}], "narrative": ["Ana Walshe, 39, a Serbian-born real estate executive at Tishman Speyer, was reported missing from her home in Cohasset, Massachusetts on January 4, 2023. Her husband Brian said she left for work on January 1.", "Investigators discovered Brian had purchased cleaning supplies, including knives and garbage bags, from a Home Depot after Ana's disappearance. His internet searches included 'how to dispose of a body.'", "Blood was found in the couple's basement and in garbage bags recovered from a trash facility. Prosecutors alleged Brian killed Ana and dismembered her body.", "Brian Walshe was charged with murder. His trial is pending. The case drew intense media coverage due to Brian's prior conviction for fraud involving fake Andy Warhol paintings."], "timeline": [{"date": "2023-01-01", "event": "Ana Walshe last seen."}, {"date": "2023-01-18", "event": "Brian Walshe charged with murder."}], "enriched": True},
    {"id": "bryan-kohberger-2022", "name": "Idaho Student Murders", "type": "Homicide", "status": "Solved", "year": 2022, "date": "November 13, 2022", "state": "Idaho", "city": "Moscow", "age": None, "gender": "Mixed", "summary": "Four University of Idaho students were stabbed to death in their off-campus home. Bryan Kohberger, a WSU criminology PhD student, was arrested. He pleaded guilty to all four murders in 2025.", "lastSeen": "November 13, 2022, King Road residence, Moscow, Latah County, Idaho", "tags": ["homicide", "Idaho", "2020s", "solved"], "sources": [{"title": "University of Idaho murders - Wikipedia", "url": "https://en.wikipedia.org/wiki/2022_University_of_Idaho_killings"}, {"title": "Kohberger arrest - NBC News", "url": "https://www.nbcnews.com/news/us-news/bryan-kohberger-idaho-students/"}, {"title": "Case details - CNN", "url": "https://www.cnn.com/us/idaho-student-killings/index.html"}], "narrative": ["On November 13, 2022, four University of Idaho students were stabbed to death in their off-campus home on King Road in Moscow, Idaho. The victims were Kaylee Goncalves (21), Madison Mogen (21), Xana Kernodle (20), and Ethan Chapin (20).", "Two other roommates were in the house and survived unharmed, apparently sleeping through the attacks. The case generated massive national attention and online speculation.", "Bryan Kohberger, 28, a criminology PhD student at nearby Washington State University, was arrested on December 30, 2022. Cell phone data placed him at the scene, and DNA on a knife sheath matched his profile.", "Kohberger initially maintained his innocence. In 2025, he changed his plea to guilty on all four counts of first-degree murder. He was sentenced to life without parole."], "timeline": [{"date": "2022-11-13", "event": "Four Idaho students murdered."}, {"date": "2022-12-30", "event": "Bryan Kohberger arrested."}], "enriched": True},
    {"id": "riley-strain-2024", "name": "Riley Strain", "type": "Accidental Death", "status": "Solved", "year": 2024, "date": "March 8, 2024", "state": "Tennessee", "city": "Nashville", "age": 22, "gender": "Male", "summary": "University of Missouri senior Riley Strain disappeared on Nashville's Broadway after being kicked out of a bar. His body was found in the Cumberland River two weeks later. His death was ruled accidental drowning.", "lastSeen": "March 8, 2024, Broadway, Nashville, Davidson County, Tennessee", "tags": ["accidental death", "Tennessee", "2020s", "solved"], "sources": [{"title": "Riley Strain case - WKRN Nashville", "url": "https://www.wkrn.com/news/riley-strain/"}, {"title": "Strain disappearance - People", "url": "https://people.com/crime/riley-strain-missing-nashville/"}, {"title": "Body found - CNN", "url": "https://www.cnn.com/2024/03/22/us/riley-strain-body-found/index.html"}], "narrative": ["On March 8, 2024, Riley Strain, a 22-year-old University of Missouri senior, disappeared during a night out on Broadway in Nashville, Tennessee. He was asked to leave Luke Bryan's bar after appearing intoxicated.", "CCTV footage tracked Strain walking toward the Cumberland River. His bank card and phone were found near the riverbank.", "After a two-week search that drew national attention, Strain's body was found in the Cumberland River on March 22, about eight miles downstream from where he was last seen.", "The medical examiner ruled his death an accidental drowning with acute alcohol intoxication as a contributing factor. The case highlighted the dangers of Nashville's riverside bar district."], "timeline": [{"date": "2024-03-08", "event": "Riley Strain disappears on Nashville Broadway."}, {"date": "2024-03-22", "event": "His body found in Cumberland River."}], "enriched": True},
    {"id": "alex-murdaugh-financial-crimes", "name": "Alex Murdaugh (financial crimes)", "type": "Fraud/Theft", "status": "Solved", "year": 2023, "date": "November 28, 2023", "state": "South Carolina", "city": "Beaufort", "age": 55, "gender": "Male", "summary": "Beyond the double murder, Alex Murdaugh was convicted of 22 counts of financial fraud, stealing nearly $12 million from clients and his law firm. He was sentenced to 27 years for the financial crimes.", "lastSeen": "Various dates, Hampton and Beaufort Counties, South Carolina", "tags": ["fraud", "South Carolina", "2020s", "solved"], "sources": [{"title": "Murdaugh financial crimes - Wikipedia", "url": "https://en.wikipedia.org/wiki/Alex_Murdaugh"}, {"title": "Fraud conviction - Post and Courier", "url": "https://www.postandcourier.com/murdaugh-updates/"}, {"title": "Financial crimes sentencing - CNN", "url": "https://www.cnn.com/2023/11/28/us/alex-murdaugh-financial-crimes-sentencing/index.html"}], "narrative": ["In addition to his murder conviction, Alex Murdaugh faced 101 charges related to financial fraud spanning over a decade of theft from clients, including vulnerable accident victims.", "Murdaugh stole nearly $12 million from his law firm's trust accounts, insurance settlements, and individual clients. Many victims were people he was supposed to be helping after tragic accidents.", "He pleaded guilty to 22 federal charges of financial fraud in November 2023 and was sentenced to 27 years in federal prison, to run concurrent with his state murder sentences.", "The financial crimes revealed a pattern of deceit that predated the murders by years. His former law firm, PMPED, was also implicated and reached settlements with victims."], "timeline": [{"date": "2023-11-28", "event": "Murdaugh pleads guilty to 22 counts of financial fraud."}, {"date": "2023-11-28", "event": "Sentenced to 27 years for financial crimes."}], "enriched": True},
    {"id": "chad-daybell-2024", "name": "Chad Daybell", "type": "Homicide", "status": "Solved", "year": 2024, "date": "May 30, 2024", "state": "Idaho", "city": "Boise", "age": 55, "gender": "Male", "summary": "Chad Daybell was convicted of murdering his first wife Tammy, his new wife Lori Vallow's two children (JJ and Tylee), and conspiracy. He was sentenced to death.", "lastSeen": "Various dates, Rexburg, Fremont County, Idaho", "tags": ["homicide", "Idaho", "2020s", "death penalty", "solved"], "sources": [{"title": "Chad Daybell trial - Wikipedia", "url": "https://en.wikipedia.org/wiki/Chad_Daybell"}, {"title": "Daybell verdict - East Idaho News", "url": "https://www.eastidahonews.com/chad-daybell/"}, {"title": "Death sentence - CNN", "url": "https://www.cnn.com/2024/05/30/us/chad-daybell-verdict/index.html"}], "narrative": ["Chad Daybell, a doomsday-focused author, was convicted in May 2024 of murdering his first wife Tammy Daybell, and his new wife Lori Vallow Daybell's two children—JJ Vallow (7) and Tylee Ryan (16).", "Daybell killed Tammy on October 19, 2019, staging it to look like natural causes. He married Lori just two weeks later. JJ and Tylee had been missing since September 2019.", "The children's remains were found buried on Daybell's property in June 2020. Tylee's body had been burned. The case was intertwined with bizarre religious beliefs about zombies and the apocalypse.", "Daybell was found guilty of all charges and sentenced to death. His wife Lori had previously been convicted and sentenced to life without parole."], "timeline": [{"date": "2019-10-19", "event": "Tammy Daybell killed."}, {"date": "2024-05-30", "event": "Chad Daybell convicted; sentenced to death."}], "enriched": True},
    {"id": "kouri-richins-2022", "name": "Eric Richins", "type": "Homicide", "status": "Solved", "year": 2022, "date": "March 4, 2022", "state": "Utah", "city": "Kamas", "age": 39, "gender": "Male", "summary": "Kouri Richins poisoned her husband Eric with a lethal fentanyl-laced cocktail in Kamas, Utah. She then wrote a children's book about grief. She was convicted of aggravated murder.", "lastSeen": "March 4, 2022, their home in Kamas, Summit County, Utah", "tags": ["homicide", "Utah", "2020s", "solved"], "sources": [{"title": "Kouri Richins case - Wikipedia", "url": "https://en.wikipedia.org/wiki/Kouri_Richins"}, {"title": "Richins case - Salt Lake Tribune", "url": "https://www.sltrib.com/news/kouri-richins/"}, {"title": "Children's book - CNN", "url": "https://www.cnn.com/2023/05/kouri-richins-childrens-book/index.html"}], "narrative": ["On March 4, 2022, Eric Richins, 39, died at his home in Kamas, Utah after drinking a cocktail his wife Kouri prepared for him. The drink was laced with a lethal dose of fentanyl.", "Kouri publicly mourned Eric's death and even self-published a children's book called 'Are You With Me?' about helping children deal with the death of a parent.", "Investigation revealed Kouri had a $1.9 million life insurance policy on Eric and had been trying to acquire fentanyl. Phone records and witness testimony linked her to the purchase of the drug.", "Kouri Richins was arrested and charged with aggravated murder. She was convicted and sentenced to life without parole. The children's book detail made the case a national sensation."], "timeline": [{"date": "2022-03-04", "event": "Eric Richins dies from fentanyl poisoning."}, {"date": "2023-05-08", "event": "Kouri Richins arrested for murder."}], "enriched": True},
    {"id": "gilgo-beach-suspect-2023", "name": "Gilgo Beach (Rex Heuermann)", "type": "Serial Killer", "status": "Solved", "year": 2023, "date": "July 13, 2023", "state": "New York", "city": "Massapequa Park", "age": 59, "gender": "Male", "summary": "Rex Heuermann, an NYC architect, was arrested and charged as the Gilgo Beach serial killer. DNA and phone data linked him to the murders of at least four women whose remains were found on Long Island.", "lastSeen": "July 13, 2023, Massapequa Park, Nassau County, New York", "tags": ["serial killer", "New York", "2020s", "solved"], "sources": [{"title": "Gilgo Beach murders - Wikipedia", "url": "https://en.wikipedia.org/wiki/Gilgo_Beach_murders"}, {"title": "Heuermann arrest - Newsday", "url": "https://www.newsday.com/long-island/gilgo-beach-murders/"}, {"title": "Heuermann charged - CNN", "url": "https://www.cnn.com/2023/07/14/us/gilgo-beach-murders-suspect-arrested/index.html"}], "narrative": ["On July 13, 2023, Rex Heuermann, 59, a New York City architect living in Massapequa Park, Long Island, was arrested and charged with three murders linked to the Gilgo Beach serial killings.", "Between 2007 and 2011, the remains of 10 people were discovered along Ocean Parkway near Gilgo Beach on Long Island's South Shore. The case went unsolved for over a decade.", "Heuermann was identified through a combination of cell phone data, burner phone records, and DNA evidence—specifically, genetic material linked to him through a family member.", "He was initially charged with killing three of the 'Gilgo Four'—Melissa Barthelemy, Megan Waterman, and Amber Costello. A fourth count for Maureen Brainard-Barnes was later added. Investigation into additional victims continues."], "timeline": [{"date": "2010-12-11", "event": "First Gilgo Beach remains discovered."}, {"date": "2023-07-13", "event": "Rex Heuermann arrested."}], "enriched": True},
    {"id": "gabby-petito-domestic-violence", "name": "Gabby Petito (domestic violence context)", "type": "Homicide", "status": "Solved", "year": 2021, "date": "August 27, 2021", "state": "Wyoming", "city": "Spread Creek", "age": 22, "gender": "Female", "summary": "The Gabby Petito case highlighted systemic failures in law enforcement response to domestic violence. A Moab, Utah police stop weeks before her murder failed to recognize her as a DV victim.", "lastSeen": "August 27, 2021, Spread Creek Dispersed Camping Area, Bridger-Teton, Wyoming", "tags": ["homicide", "domestic violence", "Wyoming", "2020s", "solved"], "sources": [{"title": "Gabby Petito domestic violence response - Wikipedia", "url": "https://en.wikipedia.org/wiki/Gabby_Petito"}, {"title": "Moab police response - Deseret News", "url": "https://www.deseret.com/gabby-petito-moab-police/"}, {"title": "DV reform - AP News", "url": "https://apnews.com/article/gabby-petito-domestic-violence/"}], "narrative": ["On August 12, 2021, police in Moab, Utah pulled over Brian Laundrie and Gabby Petito after a 911 caller reported a man slapping a woman. Officers separated the couple and identified Gabby as the aggressor.", "Body camera footage showed Gabby crying and in distress. Officers did not arrest anyone and allowed the couple to separate for the night. An independent review later found the officers made 'several unintentional mistakes.'", "Two weeks later, Gabby was dead—strangled by Laundrie in a remote Wyoming campsite. Laundrie fled to Florida and died by suicide in a nature reserve.", "The case prompted nationwide scrutiny of how police handle domestic violence calls. Two Moab officers were disciplined. Multiple states passed 'Gabby Petito laws' improving DV response protocols."], "timeline": [{"date": "2021-08-12", "event": "Moab police stop; Gabby identified as 'aggressor.'"}, {"date": "2021-08-27", "event": "Gabby Petito murdered by Laundrie."}], "enriched": True},
    {"id": "lacey-fletcher-2022", "name": "Lacey Fletcher", "type": "Homicide", "status": "Solved", "year": 2022, "date": "January 3, 2022", "state": "Louisiana", "city": "Slaughter", "age": 36, "gender": "Female", "summary": "Lacey Fletcher was found dead fused to a couch in her parents' home in Slaughter, Louisiana. She had not moved from the couch in over a decade. Her parents were charged with second-degree murder.", "lastSeen": "January 3, 2022, parents' home in Slaughter, East Feliciana Parish, Louisiana", "tags": ["homicide", "neglect", "Louisiana", "2020s", "solved"], "sources": [{"title": "Death of Lacey Fletcher - Wikipedia", "url": "https://en.wikipedia.org/wiki/Death_of_Lacey_Fletcher"}, {"title": "Fletcher case - The Advocate", "url": "https://www.theadvocate.com/baton_rouge/news/lacey-fletcher/"}, {"title": "Parents charged - CNN", "url": "https://www.cnn.com/2022/lacey-fletcher-parents-charged/index.html"}], "narrative": ["On January 3, 2022, first responders in Slaughter, Louisiana found the body of Lacey Fletcher, 36, fused to a couch in her parents' home. She was covered in waste and had been sitting in the same spot for over 12 years.", "Lacey had been diagnosed with locked-in syndrome and social anxiety but was able to speak and move. Her parents, Sheila and Clay Fletcher, were prominent members of the community.", "The coroner found Lacey weighed about 96 pounds at death and suffered from severe malnutrition, sepsis, bone infections, and chronic neglect. Her body had literally fused into the couch cushions.", "Sheila and Clay Fletcher were charged with second-degree murder. The case raised questions about how neighbors and community members could have been unaware of Lacey's condition for so long."], "timeline": [{"date": "2022-01-03", "event": "Lacey Fletcher found dead."}, {"date": "2022-06-01", "event": "Parents charged with second-degree murder."}], "enriched": True},
    {"id": "sarah-boone-2020", "name": "Jorge Torres Jr.", "type": "Homicide", "status": "Solved", "year": 2020, "date": "February 24, 2020", "state": "Florida", "city": "Winter Park", "age": 42, "gender": "Male", "summary": "Sarah Boone zipped her boyfriend Jorge Torres Jr. into a suitcase during a drinking game and left him to die. She recorded video of him begging to be let out. She was convicted of second-degree murder.", "lastSeen": "February 24, 2020, their apartment, Winter Park, Orange County, Florida", "tags": ["homicide", "Florida", "2020s", "solved"], "sources": [{"title": "Sarah Boone case - Wikipedia", "url": "https://en.wikipedia.org/wiki/Sarah_Boone_(criminal)"}, {"title": "Boone trial - Orlando Sentinel", "url": "https://www.orlandosentinel.com/crime/sarah-boone/"}, {"title": "Suitcase death - CNN", "url": "https://www.cnn.com/2024/sarah-boone-suitcase-murder/index.html"}], "narrative": ["On February 24, 2020, Sarah Boone called 911 saying she found her boyfriend Jorge Torres Jr., 42, dead inside a suitcase at their apartment in Winter Park, Florida.", "Boone told police they had been playing a drinking game of hide-and-seek. She claimed she zipped Jorge into a suitcase as a joke and fell asleep, forgetting he was inside.", "However, videos on Boone's phone showed Torres calling out and begging to be released while Boone laughed and refused to let him out. She told him 'that's what you get.'", "Boone went through 15 different attorneys before trial. She was convicted of second-degree murder in 2024."], "timeline": [{"date": "2020-02-24", "event": "Jorge Torres Jr. dies inside a suitcase."}, {"date": "2024-10-22", "event": "Sarah Boone convicted of second-degree murder."}], "enriched": True},
    {"id": "cleo-smith-2021", "name": "Cleo Smith (rescue)", "type": "Kidnapping", "status": "Solved", "year": 2021, "date": "October 16, 2021", "state": "Australia", "city": "Carnarvon", "country": "Australia", "age": 4, "gender": "Female", "summary": "Four-year-old Cleo Smith was abducted from her family's tent at a campsite in Western Australia. She was found alive 18 days later in a locked house. Terence Kelly pleaded guilty to child stealing.", "lastSeen": "October 16, 2021, Blowholes campsite, Macleod, Western Australia", "tags": ["kidnapping", "child", "Australia", "2020s", "solved"], "sources": [{"title": "Disappearance of Cleo Smith - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Cleo_Smith"}, {"title": "Cleo found - ABC Australia", "url": "https://www.abc.net.au/news/cleo-smith-found/"}, {"title": "Kelly conviction - The Guardian", "url": "https://www.theguardian.com/australia-news/cleo-smith"}], "narrative": ["Four-year-old Cleo Smith vanished from her family's tent at the Blowholes campsite near Carnarvon, Western Australia on October 16, 2021. The tent zipper was open to a height she couldn't reach.", "A massive search and investigation followed. Western Australia Police offered a $1 million reward. The case gripped Australia for 18 days.", "On November 3, 2021, police broke into a locked house in Carnarvon and found Cleo alive and well. She said 'My name is Cleo' when officers entered.", "Terence Darrell Kelly, 36, was arrested at the scene. He had taken Cleo and was playing with her and buying her toys. He pleaded guilty to child stealing and was sentenced to 13 years and 6 months."], "timeline": [{"date": "2021-10-16", "event": "Cleo Smith abducted from tent."}, {"date": "2021-11-03", "event": "Cleo found alive; Kelly arrested."}], "enriched": True},
    {"id": "constance-marten-2023", "name": "Constance Marten & Mark Gordon", "type": "Homicide", "status": "Solved", "year": 2023, "date": "February 28, 2023", "state": "United Kingdom", "city": "Brighton", "country": "United Kingdom", "age": None, "gender": "Female", "summary": "Constance Marten and Mark Gordon went on the run across England after their newborn baby died. The baby's body was found in a bag in Brighton. Both were convicted of manslaughter by gross negligence.", "lastSeen": "January-February 2023, various locations across England", "tags": ["homicide", "infant", "United Kingdom", "2020s", "solved"], "sources": [{"title": "Constance Marten case - BBC", "url": "https://www.bbc.com/news/uk-england-constance-marten"}, {"title": "Baby Victoria found - The Guardian", "url": "https://www.theguardian.com/uk-news/constance-marten-mark-gordon"}, {"title": "Trial verdict - Sky News", "url": "https://news.sky.com/story/constance-marten-mark-gordon/"}], "narrative": ["In January 2023, aristocrat Constance Marten and her partner Mark Gordon went on the run across England. Marten had given birth in the back of a car and the couple avoided hospitals and authorities.", "Their car was found abandoned and on fire on the M61 motorway. A nationwide manhunt followed as police grew increasingly concerned for the welfare of the newborn.", "On February 28, 2023, Marten and Gordon were found on a park bench in Brighton. They did not have the baby. Police discovered the remains of baby Victoria in a bag in a shed nearby.", "Both were convicted of manslaughter by gross negligence. Gordon was also convicted of perverting the course of justice. The baby had died from cold exposure within hours of birth."], "timeline": [{"date": "2023-01-05", "event": "Car found abandoned; manhunt begins."}, {"date": "2023-02-28", "event": "Marten and Gordon found; baby's body discovered."}], "enriched": True},
    {"id": "letby-trial-2023", "name": "Lucy Letby Victims", "type": "Serial Murder", "status": "Solved", "year": 2023, "date": "August 18, 2023", "state": "United Kingdom", "city": "Chester", "country": "United Kingdom", "age": None, "gender": "Mixed", "summary": "Neonatal nurse Lucy Letby was convicted of murdering seven babies and attempting to murder six others at the Countess of Chester Hospital. She received a whole-life order.", "lastSeen": "2015-2016, Countess of Chester Hospital, Chester, England", "tags": ["serial murder", "infant", "United Kingdom", "2020s", "solved"], "sources": [{"title": "Lucy Letby - Wikipedia", "url": "https://en.wikipedia.org/wiki/Lucy_Letby"}, {"title": "Letby trial - BBC", "url": "https://www.bbc.com/news/uk-england-merseyside-lucy-letby"}, {"title": "Letby conviction - The Guardian", "url": "https://www.theguardian.com/uk-news/lucy-letby"}], "narrative": ["Lucy Letby, a neonatal nurse at the Countess of Chester Hospital, was convicted in August 2023 of murdering seven babies and attempting to murder six others between June 2015 and June 2016.", "Letby killed babies through methods including injecting air into their bloodstreams, poisoning them with insulin, overfeeding them with milk, and causing trauma. She targeted the most vulnerable premature infants.", "Senior doctors had raised concerns about Letby in 2016 when they noticed a correlation between her shifts and unexplained baby deaths. Hospital management initially failed to act and ordered the doctors to apologize to Letby.", "Letby was sentenced to a whole-life order—meaning she will never be released. The case led to a public inquiry (the Thirlwall Inquiry) into the hospital's failures. She was convicted of a further attempted murder at a retrial in 2024."], "timeline": [{"date": "2020-11-10", "event": "Letby arrested."}, {"date": "2023-08-18", "event": "Convicted of 7 murders and 6 attempted murders; whole-life order."}], "enriched": True},
    {"id": "grace-millane-new-zealand-2018", "name": "Grace Millane", "type": "Homicide", "status": "Solved", "year": 2018, "date": "December 1, 2018", "state": "New Zealand", "city": "Auckland", "country": "New Zealand", "age": 22, "gender": "Female", "summary": "British backpacker Grace Millane was murdered by a man she met on Tinder in Auckland, New Zealand on her 22nd birthday. Jesse Kempson was convicted of murder.", "lastSeen": "December 1, 2018, CityLife Hotel, Auckland, New Zealand", "tags": ["homicide", "New Zealand", "2010s", "solved"], "sources": [{"title": "Murder of Grace Millane - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Grace_Millane"}, {"title": "Millane case - NZ Herald", "url": "https://www.nzherald.co.nz/grace-millane/"}, {"title": "Kempson conviction - BBC", "url": "https://www.bbc.com/news/world-asia-grace-millane"}], "narrative": ["Grace Millane, a 22-year-old British backpacker, was killed on December 1, 2018—her birthday—after a Tinder date in Auckland, New Zealand. She had been traveling the world after graduating from university.", "Her date, Jesse Kempson, strangled her in his hotel room. He took intimate photos of her body, stuffed it in a suitcase, and buried it in a wooded area outside Auckland.", "Kempson claimed Grace died accidentally during consensual rough sex. The jury rejected this defense. He was convicted of murder in November 2019.", "Grace's father David gave an emotional press conference in Auckland. The case sparked a national conversation in New Zealand about violence against women. Kempson's name was initially suppressed under New Zealand law."], "timeline": [{"date": "2018-12-01", "event": "Grace Millane murdered in Auckland."}, {"date": "2019-11-22", "event": "Kempson convicted of murder."}], "enriched": True},
    {"id": "daniel-morcombe-2003", "name": "Daniel Morcombe", "type": "Homicide", "status": "Solved", "year": 2003, "date": "December 7, 2003", "state": "Australia", "city": "Sunshine Coast", "country": "Australia", "age": 13, "gender": "Male", "summary": "Thirteen-year-old Daniel Morcombe was abducted from a bus stop on Queensland's Sunshine Coast. His killer was identified through a covert police operation eight years later.", "lastSeen": "December 7, 2003, bus stop under the Kiel Mountain Road overpass, Woombye, Queensland, Australia", "tags": ["homicide", "child", "Australia", "2000s", "solved"], "sources": [{"title": "Murder of Daniel Morcombe - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Daniel_Morcombe"}, {"title": "Morcombe case - ABC", "url": "https://www.abc.net.au/news/daniel-morcombe/"}, {"title": "Cowan conviction - Brisbane Times", "url": "https://www.brisbanetimes.com.au/national/queensland/daniel-morcombe/"}], "narrative": ["On December 7, 2003, thirteen-year-old Daniel Morcombe was waiting for a bus under the Kiel Mountain Road overpass on the Sunshine Coast, Queensland. The bus was running late and Daniel accepted a ride from a stranger.", "The case became one of Australia's most high-profile missing persons investigations. Daniel's parents, Bruce and Denise, campaigned tirelessly, establishing the Daniel Morcombe Foundation for child safety.", "In 2011, police identified Brett Peter Cowan through an elaborate covert operation. Undercover officers posed as criminals and befriended Cowan, who eventually confessed and led them to Daniel's remains.", "Cowan was convicted of murder in 2014 and sentenced to life with a minimum of 20 years. The Daniel Morcombe Foundation has become Australia's leading child safety organization."], "timeline": [{"date": "2003-12-07", "event": "Daniel Morcombe abducted."}, {"date": "2014-03-13", "event": "Cowan convicted of murder."}], "enriched": True},
    {"id": "ivan-milat-backpacker-1990s", "name": "Ivan Milat Victims (Backpacker Murders)", "type": "Serial Killer Victims", "status": "Solved", "year": 1994, "date": "September 1992", "state": "Australia", "city": "Belanglo", "country": "Australia", "age": None, "gender": "Mixed", "summary": "Ivan Milat murdered seven backpackers in the Belanglo State Forest south of Sydney. Their bodies were found in 1992-1993. Milat was convicted in 1996 and died in prison in 2019.", "lastSeen": "1989-1992, Belanglo State Forest, New South Wales, Australia", "tags": ["serial killer", "Australia", "1990s", "solved"], "sources": [{"title": "Ivan Milat - Wikipedia", "url": "https://en.wikipedia.org/wiki/Ivan_Milat"}, {"title": "Backpacker murders - ABC Australia", "url": "https://www.abc.net.au/news/ivan-milat/"}, {"title": "Milat death - Sydney Morning Herald", "url": "https://www.smh.com.au/national/ivan-milat-dies/"}], "narrative": ["Between 1989 and 1992, Ivan Milat abducted and murdered seven backpackers—both local and international—in the Belanglo State Forest, about 150 km southwest of Sydney.", "The victims' remains were discovered by orienteers in September 1992 and subsequent searches through 1993. All had been stabbed or shot, some multiple times. Several had been subjected to a prolonged ordeal.", "Milat was arrested in 1994 after Paul Onions, a British backpacker who had escaped an abduction attempt in 1990, identified him. Evidence linking Milat to the victims was found at his home.", "Milat was convicted of seven murders and sentenced to seven consecutive life sentences in 1996. He maintained his innocence and died of cancer in prison on October 27, 2019."], "timeline": [{"date": "1992-09-19", "event": "First bodies found in Belanglo State Forest."}, {"date": "1996-07-27", "event": "Ivan Milat convicted of seven murders."}], "enriched": True},
    {"id": "william-tyrrell-2014", "name": "William Tyrrell", "type": "Missing Person", "status": "Unsolved", "year": 2014, "date": "September 12, 2014", "state": "Australia", "city": "Kendall", "country": "Australia", "age": 3, "gender": "Male", "summary": "Three-year-old William Tyrrell vanished from his foster grandmother's garden in Kendall, New South Wales while wearing a Spider-Man suit. No trace has been found despite Australia's largest investigation.", "lastSeen": "September 12, 2014, foster grandmother's home, Kendall, New South Wales, Australia", "tags": ["missing person", "child", "Australia", "2010s", "unsolved"], "sources": [{"title": "Disappearance of William Tyrrell - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_William_Tyrrell"}, {"title": "William Tyrrell - ABC", "url": "https://www.abc.net.au/news/william-tyrrell/"}, {"title": "Search continues - Sydney Morning Herald", "url": "https://www.smh.com.au/national/william-tyrrell/"}], "narrative": ["On September 12, 2014, William Tyrrell, three years old, was playing in his foster grandmother's garden in Kendall, New South Wales wearing his favorite Spider-Man costume. He vanished within minutes.", "The case became Australia's most extensive missing persons investigation. Police explored multiple theories including abduction by a stranger, involvement of someone known to the family, and accidental death.", "In 2021, police conducted extensive searches of the foster grandmother's property and surrounding bushland, suggesting they were investigating whether William died accidentally and was covered up. No remains were found.", "A $1 million reward has been offered. Multiple persons of interest have been investigated. As of 2024, no one has been charged and William has never been found."], "timeline": [{"date": "2014-09-12", "event": "William Tyrrell vanishes."}, {"date": "2021-11-01", "event": "Major police search of foster grandmother's property."}], "enriched": True},
    {"id": "peter-falconio-2001", "name": "Peter Falconio", "type": "Homicide", "status": "Solved", "year": 2001, "date": "July 14, 2001", "state": "Australia", "city": "Barrow Creek", "country": "Australia", "age": 28, "gender": "Male", "summary": "British tourist Peter Falconio was murdered on a remote outback highway in the Northern Territory. His girlfriend Joanne Lees escaped. Bradley Murdoch was convicted but Falconio's body was never found.", "lastSeen": "July 14, 2001, Stuart Highway near Barrow Creek, Northern Territory, Australia", "tags": ["homicide", "Australia", "2000s", "solved"], "sources": [{"title": "Murder of Peter Falconio - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Peter_Falconio"}, {"title": "Falconio case - ABC", "url": "https://www.abc.net.au/news/peter-falconio/"}, {"title": "Murdoch conviction - BBC", "url": "https://www.bbc.com/news/world-asia-peter-falconio"}], "narrative": ["On July 14, 2001, British tourists Peter Falconio, 28, and Joanne Lees, 27, were driving along the Stuart Highway in the remote Northern Territory when a man in a pickup truck signaled them to stop.", "The man shot Falconio and bound Lees, who managed to escape into the bush. She hid for five hours before flagging down a passing truck.", "DNA evidence on Lees' clothing and on cable ties used to bind her linked the crime to Bradley Murdoch, a drug runner. He was convicted of murder in 2005.", "Falconio's body has never been found. Murdoch has never revealed its location. He was sentenced to life with a minimum of 28 years."], "timeline": [{"date": "2001-07-14", "event": "Peter Falconio murdered on Stuart Highway."}, {"date": "2005-12-13", "event": "Murdoch convicted of murder."}], "enriched": True},
    {"id": "joanna-dennehy-2013", "name": "Joanna Dennehy Victims", "type": "Serial Killer", "status": "Solved", "year": 2013, "date": "March-April 2013", "state": "United Kingdom", "city": "Peterborough", "country": "United Kingdom", "age": None, "gender": "Male", "summary": "Joanna Dennehy murdered three men and stabbed two others in Peterborough and Hereford. She is one of only three women in the UK to receive a whole-life order.", "lastSeen": "March-April 2013, Peterborough, Cambridgeshire and Hereford, Herefordshire, England", "tags": ["serial killer", "United Kingdom", "2010s", "solved"], "sources": [{"title": "Joanna Dennehy - Wikipedia", "url": "https://en.wikipedia.org/wiki/Joanna_Dennehy"}, {"title": "Dennehy case - BBC", "url": "https://www.bbc.com/news/uk-england-cambridgeshire-joanna-dennehy"}, {"title": "Dennehy sentencing - The Guardian", "url": "https://www.theguardian.com/uk-news/joanna-dennehy"}], "narrative": ["In March 2013, Joanna Dennehy, 31, murdered three men in Peterborough, Cambridgeshire: her landlord Kevin Lee, Lukasz Slaboszewski, and John Chapman. She stabbed each multiple times.", "After the killings, Dennehy went on the run with an accomplice, Gary Stretch. In Hereford, she randomly attacked two men walking their dogs, stabbing both. They survived.", "Dennehy showed no remorse and later told a psychiatrist she killed because she wanted 'to have my fun.' She was diagnosed with psychopathy and antisocial personality disorder.", "Dennehy pleaded guilty to three murders and two attempted murders. She was sentenced to a whole-life order in 2014—only the third woman in England to receive such a sentence."], "timeline": [{"date": "2013-03-19", "event": "First murder."}, {"date": "2013-04-02", "event": "Two men randomly stabbed in Hereford."}, {"date": "2014-02-28", "event": "Dennehy sentenced to whole-life order."}], "enriched": True},
    {"id": "natalie-mcnally-2022", "name": "Natalie McNally", "type": "Homicide", "status": "Solved", "year": 2022, "date": "December 18, 2022", "state": "United Kingdom", "city": "Lurgan", "country": "United Kingdom", "age": 32, "gender": "Female", "summary": "Natalie McNally, who was 15 weeks pregnant, was stabbed to death in her home in Lurgan, Northern Ireland. Stephen McCullagh was convicted of her murder.", "lastSeen": "December 18, 2022, her home in Lurgan, County Armagh, Northern Ireland", "tags": ["homicide", "United Kingdom", "2020s", "solved"], "sources": [{"title": "Murder of Natalie McNally - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Natalie_McNally"}, {"title": "McNally case - BBC Northern Ireland", "url": "https://www.bbc.com/news/uk-northern-ireland-natalie-mcnally"}, {"title": "McCullagh convicted - Belfast Telegraph", "url": "https://www.belfasttelegraph.co.uk/news/natalie-mcnally/"}], "narrative": ["On December 18, 2022, Natalie McNally, 32, was stabbed to death in her home in Lurgan, County Armagh, Northern Ireland. She was 15 weeks pregnant.", "Natalie's family campaigned publicly for justice. She had worked as a civil servant and was described as a loving sister and daughter.", "Stephen McCullagh was arrested and charged with murder. Evidence included DNA, phone data, and CCTV footage placing him near Natalie's home.", "McCullagh was convicted of murder in 2024. The case highlighted violence against women and the particular vulnerability of pregnant women to domestic violence."], "timeline": [{"date": "2022-12-18", "event": "Natalie McNally murdered."}, {"date": "2024-01-01", "event": "McCullagh convicted of murder."}], "enriched": True},
    {"id": "brianna-ghey-2023", "name": "Brianna Ghey", "type": "Homicide", "status": "Solved", "year": 2023, "date": "February 11, 2023", "state": "United Kingdom", "city": "Warrington", "country": "United Kingdom", "age": 16, "gender": "Female", "summary": "Sixteen-year-old transgender girl Brianna Ghey was murdered in a park in Warrington by two 15-year-olds. The killers had planned the attack for weeks. Both received life sentences.", "lastSeen": "February 11, 2023, Culcheth Linear Park, Warrington, Cheshire, England", "tags": ["homicide", "child", "United Kingdom", "2020s", "solved"], "sources": [{"title": "Murder of Brianna Ghey - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Brianna_Ghey"}, {"title": "Ghey case - BBC", "url": "https://www.bbc.com/news/uk-england-manchester-brianna-ghey"}, {"title": "Trial details - The Guardian", "url": "https://www.theguardian.com/uk-news/brianna-ghey"}], "narrative": ["On February 11, 2023, Brianna Ghey, a 16-year-old transgender girl, was stabbed 28 times in Culcheth Linear Park in Warrington, Cheshire. She died at the scene.", "Her killers, Scarlett Jenkinson and Eddie Ratcliffe, both 15, had planned the attack for weeks. Messages between them showed they had discussed methods of killing and had targeted Brianna.", "Jenkinson, who had an obsession with torture and serial killers, lured Brianna to the park where Ratcliffe stabbed her. They tried to cover their tracks by wiping their phones.", "Both were convicted of murder in February 2024. Jenkinson received a minimum term of 22 years and Ratcliffe 20 years. Brianna's mother Esther campaigned for stricter controls on children's social media access."], "timeline": [{"date": "2023-02-11", "event": "Brianna Ghey murdered."}, {"date": "2024-02-02", "event": "Jenkinson and Ratcliffe convicted; sentenced to life."}], "enriched": True},
    {"id": "jaylen-fleer-2020", "name": "Jaylen Fleer", "type": "Sexual Exploitation", "status": "Solved", "year": 2020, "date": "June 2020", "state": "California", "city": "San Diego", "age": 27, "gender": "Male", "summary": "San Diego County sheriff's deputy Jaylen Fleer was sentenced to 12 years for sexually exploiting minors. He was caught in a sting operation when he arranged to meet a 14-year-old.", "lastSeen": "June 2020, San Diego County, California", "tags": ["sexual exploitation", "California", "2020s", "solved"], "sources": [{"title": "Jaylen Fleer case - San Diego Union-Tribune", "url": "https://www.sandiegouniontribune.com/news/crime/jaylen-fleer/"}, {"title": "Deputy arrested - NBC San Diego", "url": "https://www.nbcsandiego.com/news/local/jaylen-fleer-deputy/"}], "narrative": ["In June 2020, Jaylen Fleer, 27, a San Diego County sheriff's deputy, was arrested after arranging to meet a person he believed to be a 14-year-old girl for sex.", "Investigation revealed Fleer had been sending explicit messages to minors and had previously engaged in sexual activity with a teenage girl.", "Fleer pleaded guilty to multiple felony charges including lewd acts on a minor and meeting a minor with the intent to commit a sex act.", "He was sentenced to 12 years in state prison. The case highlighted concerns about law enforcement officers abusing their positions."], "timeline": [{"date": "2020-06-01", "event": "Fleer arrested in sting operation."}, {"date": "2021-04-01", "event": "Sentenced to 12 years."}], "enriched": True},
    {"id": "murdaugh-boat-crash-2019", "name": "Mallory Beach", "type": "Wrongful Death", "status": "Solved", "year": 2019, "date": "February 24, 2019", "state": "South Carolina", "city": "Beaufort", "age": 19, "gender": "Female", "summary": "Nineteen-year-old Mallory Beach died in a boat crash caused by Paul Murdaugh driving drunk. The Murdaugh family's influence was used to obstruct the investigation. Paul was later murdered by his father Alex.", "lastSeen": "February 24, 2019, Archers Creek, Beaufort County, South Carolina", "tags": ["wrongful death", "South Carolina", "2010s", "solved"], "sources": [{"title": "Mallory Beach death - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murdaugh_murders"}, {"title": "Beach case - Island Packet", "url": "https://www.islandpacket.com/news/mallory-beach/"}, {"title": "Murdaugh connections - FITSNews", "url": "https://www.fitsnews.com/mallory-beach-murdaugh/"}], "narrative": ["On February 24, 2019, a boat driven by an intoxicated Paul Murdaugh crashed into a bridge piling near Parris Island, South Carolina. Nineteen-year-old Mallory Beach was thrown from the boat. Her body was found a week later.", "After the crash, Alex Murdaugh arrived at the hospital and allegedly tried to influence the investigation, coaching passengers on what to say. The Murdaugh family's legal connections in the area added to suspicions of a cover-up.", "Paul Murdaugh was charged with boating under the influence causing death. The case exposed the Murdaugh family's outsized influence in the Lowcountry legal community.", "Before the case could go to trial, Paul and his mother Maggie were murdered by Alex Murdaugh in June 2021—a crime Alex committed partly to distract from his financial crimes being uncovered."], "timeline": [{"date": "2019-02-24", "event": "Boat crash; Mallory Beach killed."}, {"date": "2021-06-07", "event": "Paul Murdaugh murdered by his father."}], "enriched": True},
    {"id": "heather-elvis-2013", "name": "Heather Elvis", "type": "Missing Person", "status": "Solved", "year": 2013, "date": "December 18, 2013", "state": "South Carolina", "city": "Myrtle Beach", "age": 20, "gender": "Female", "summary": "Twenty-year-old Heather Elvis vanished from Peachtree Landing near Myrtle Beach. Sidney and Tammy Moorer, a married couple Heather had been involved with, were convicted of kidnapping and murder.", "lastSeen": "December 18, 2013, Peachtree Landing boat ramp, Socastee, Horry County, South Carolina", "tags": ["missing person", "South Carolina", "2010s", "solved"], "sources": [{"title": "Disappearance of Heather Elvis - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Heather_Elvis"}, {"title": "Elvis case - Myrtle Beach Sun News", "url": "https://www.myrtlebeachonline.com/news/heather-elvis/"}, {"title": "Moorer trial - WMBF", "url": "https://www.wmbfnews.com/heather-elvis-moorer/"}], "narrative": ["On December 18, 2013, Heather Elvis, a 20-year-old waitress, disappeared from the Peachtree Landing boat ramp near Myrtle Beach, South Carolina. Her car was found at the landing with the door open.", "Heather had been having a relationship with Sidney Moorer, a married man. When his wife Tammy discovered the affair, she became enraged and threatening.", "Phone records showed Sidney called Heather in the early morning hours of her disappearance, luring her to Peachtree Landing. GPS data placed the Moorers' truck at the landing.", "Sidney Moorer was convicted of kidnapping and murder in separate trials. Tammy was convicted of kidnapping and conspiracy. Heather's body has never been found."], "timeline": [{"date": "2013-12-18", "event": "Heather Elvis vanishes."}, {"date": "2019-08-01", "event": "Sidney Moorer convicted of murder."}], "enriched": True},
    {"id": "holly-bobo-2011", "name": "Holly Bobo", "type": "Homicide", "status": "Solved", "year": 2011, "date": "April 13, 2011", "state": "Tennessee", "city": "Darden", "age": 20, "gender": "Female", "summary": "Nursing student Holly Bobo was abducted from her home in Darden, Tennessee. Her brother witnessed a man in camouflage leading her into the woods. Three men were convicted; her remains were found in 2014.", "lastSeen": "April 13, 2011, her family home in Darden, Decatur County, Tennessee", "tags": ["homicide", "Tennessee", "2010s", "solved"], "sources": [{"title": "Murder of Holly Bobo - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Holly_Bobo"}, {"title": "Bobo case - The Tennessean", "url": "https://www.tennessean.com/story/news/crime/holly-bobo/"}, {"title": "Adams trial - WSMV", "url": "https://www.wsmv.com/news/holly-bobo-trial/"}], "narrative": ["On April 13, 2011, Holly Bobo, a 20-year-old nursing student, was abducted from her home in rural Darden, Tennessee. Her brother saw a man in camouflage leading her into the woods behind their house.", "The case became one of the largest searches in Tennessee history. Holly's remains were found in 2014 in a rural area of Decatur County.", "Three men—Zachary Adams, Jason Autry, and John Dylan Adams—were implicated. Autry testified as a cooperating witness, describing how Holly was raped and murdered.", "Zachary Adams was convicted of kidnapping, rape, and murder, receiving life plus 50 years. Jason Autry received a reduced sentence for his testimony. John Dylan Adams was convicted of lesser charges."], "timeline": [{"date": "2011-04-13", "event": "Holly Bobo abducted."}, {"date": "2014-09-07", "event": "Her remains found."}, {"date": "2017-09-22", "event": "Zachary Adams convicted."}], "enriched": True},
    {"id": "sherri-papini-hoax-2022", "name": "Sherri Papini (hoax)", "type": "Hoax/Fraud", "status": "Solved", "year": 2022, "date": "March 2, 2022", "state": "California", "city": "Redding", "age": 39, "gender": "Female", "summary": "Sherri Papini was convicted of faking her own kidnapping in 2016. She had claimed she was abducted while jogging and tortured by two Hispanic women. She had actually been staying with an ex-boyfriend.", "lastSeen": "November 2, 2016 - November 24, 2016 (claimed kidnapping period), Redding, California", "tags": ["hoax", "California", "2020s", "solved"], "sources": [{"title": "Sherri Papini case - Wikipedia", "url": "https://en.wikipedia.org/wiki/Disappearance_of_Sherri_Papini"}, {"title": "Papini conviction - Sacramento Bee", "url": "https://www.sacbee.com/news/california/sherri-papini/"}, {"title": "Papini confession - CNN", "url": "https://www.cnn.com/2022/03/sherri-papini-hoax/index.html"}], "narrative": ["In November 2016, Sherri Papini, a mother of two from Redding, California, disappeared while jogging. She reappeared 22 days later on Thanksgiving Day, bound and branded, claiming two Hispanic women had kidnapped and tortured her.", "Papini's story generated massive media coverage and public sympathy. She was labeled a 'supermom' who had been taken from her family. Law enforcement spent thousands of hours investigating.", "In 2020, DNA evidence led investigators to James Reyes, an ex-boyfriend. He revealed that Papini had stayed with him voluntarily. She had inflicted her own injuries and branded herself.", "Papini was arrested in 2022 and pleaded guilty to lying to federal agents and mail fraud. She was sentenced to 18 months in federal prison. The case diverted resources from real missing persons cases."], "timeline": [{"date": "2016-11-02", "event": "Papini 'disappears' while jogging."}, {"date": "2022-04-18", "event": "Pleads guilty to faking her kidnapping."}], "enriched": True},
    {"id": "jennifer-pan-2010", "name": "Jennifer Pan (case)", "type": "Homicide", "status": "Solved", "year": 2010, "date": "November 8, 2010", "state": "Canada", "city": "Markham", "country": "Canada", "age": 24, "gender": "Female", "summary": "Jennifer Pan orchestrated a fake home invasion in Markham, Ontario to murder her parents. Her mother was killed and her father survived. Pan had been living a double life for years.", "lastSeen": "November 8, 2010, Pan family home, Markham, Ontario, Canada", "tags": ["homicide", "Canada", "2010s", "solved"], "sources": [{"title": "Jennifer Pan - Wikipedia", "url": "https://en.wikipedia.org/wiki/Jennifer_Pan"}, {"title": "Pan case - Toronto Star", "url": "https://www.thestar.com/news/crime/jennifer-pan/"}, {"title": "Pan trial - CBC", "url": "https://www.cbc.ca/news/canada/toronto/jennifer-pan/"}], "narrative": ["On November 8, 2010, three armed men entered the Pan family home in Markham, Ontario. They shot Bich Ha Pan, killing her, and shot her husband Hann, who survived.", "Daughter Jennifer, 24, initially appeared to be a victim, telling police the intruders had tied her up. However, inconsistencies in her story led police to investigate further.", "It emerged that Jennifer had been living an elaborate lie for years—fabricating a university education, pretending to have a job, and hiding a relationship her parents disapproved of. When her parents discovered the deception and threatened to cut her off, she hired hitmen.", "Jennifer Pan and her co-conspirators were convicted of first-degree murder and attempted murder. She was sentenced to life with no parole for 25 years."], "timeline": [{"date": "2010-11-08", "event": "Home invasion; Bich Ha Pan killed."}, {"date": "2014-12-13", "event": "Jennifer Pan convicted; sentenced to life."}], "enriched": True},
    {"id": "luka-magnotta-2012", "name": "Jun Lin (Luka Magnotta)", "type": "Homicide", "status": "Solved", "year": 2012, "date": "May 24, 2012", "state": "Canada", "city": "Montreal", "country": "Canada", "age": 33, "gender": "Male", "summary": "Luka Magnotta murdered and dismembered Chinese student Jun Lin in Montreal, mailing body parts to political parties. He posted the killing online and fled to Europe before being caught in Berlin.", "lastSeen": "May 24, 2012, Montreal, Quebec, Canada", "tags": ["homicide", "Canada", "2010s", "solved"], "sources": [{"title": "Luka Magnotta - Wikipedia", "url": "https://en.wikipedia.org/wiki/Luka_Magnotta"}, {"title": "Magnotta case - Montreal Gazette", "url": "https://montrealgazette.com/news/local-news/luka-magnotta/"}, {"title": "Don't F**k with Cats - Netflix", "url": "https://www.netflix.com/title/81031373"}], "narrative": ["On May 24, 2012, Luka Magnotta murdered Jun Lin, a 33-year-old Chinese international student, in his Montreal apartment. He filmed the killing and posted it online.", "Magnotta then dismembered the body and mailed body parts to the offices of Canadian political parties and elementary schools. A foot was sent to the Conservative Party and a hand to the Liberal Party.", "Magnotta fled to Europe, triggering an international manhunt. He was recognized by an employee at an internet café in Berlin, Germany and arrested on June 4, 2012.", "Prior to the murder, online sleuths had attempted to identify Magnotta after he posted videos of himself killing kittens—a story documented in the Netflix series 'Don't F**k with Cats.' Magnotta was convicted of first-degree murder and sentenced to life."], "timeline": [{"date": "2012-05-24", "event": "Jun Lin murdered; video posted online."}, {"date": "2012-06-04", "event": "Magnotta arrested in Berlin."}, {"date": "2014-12-23", "event": "Convicted of first-degree murder."}], "enriched": True},
    {"id": "robert-pickton-farm-2002", "name": "Robert Pickton Victims", "type": "Serial Killer Victims", "status": "Solved", "year": 2002, "date": "February 22, 2002", "state": "Canada", "city": "Port Coquitlam", "country": "Canada", "age": None, "gender": "Female", "summary": "Pig farmer Robert Pickton was convicted of six murders but linked to as many as 49 missing women from Vancouver's Downtown Eastside. Remains were found on his farm. He died in prison in 2024.", "lastSeen": "1983-2002, Pickton farm, Port Coquitlam, British Columbia, Canada", "tags": ["serial killer", "Canada", "2000s", "solved"], "sources": [{"title": "Robert Pickton - Wikipedia", "url": "https://en.wikipedia.org/wiki/Robert_Pickton"}, {"title": "Pickton case - Vancouver Sun", "url": "https://www.vancouversun.com/news/robert-pickton/"}, {"title": "Pickton death - CBC", "url": "https://www.cbc.ca/news/canada/british-columbia/robert-pickton-dies/"}], "narrative": ["Robert Pickton, a pig farmer from Port Coquitlam, British Columbia, was linked to the disappearances of dozens of women from Vancouver's Downtown Eastside—many of them Indigenous women and sex workers.", "Police searched his farm beginning in 2002, finding the DNA of 33 women on the property. Pickton told an undercover officer he had killed 49 women and was 'sloppy' about cleaning up.", "He was convicted of six counts of second-degree murder in 2007 and sentenced to life with no parole for 25 years. The remaining 20 charges were stayed.", "Pickton died in prison on May 31, 2024 after being attacked by a fellow inmate. The case exposed systemic failures in how police handled missing persons cases involving marginalized women."], "timeline": [{"date": "2002-02-22", "event": "Pickton farm searched; evidence found."}, {"date": "2007-12-09", "event": "Pickton convicted of six murders."}, {"date": "2024-05-31", "event": "Pickton dies in prison."}], "enriched": True},
    {"id": "mollie-tibbetts-2018", "name": "Mollie Tibbetts", "type": "Homicide", "status": "Solved", "year": 2018, "date": "July 18, 2018", "state": "Iowa", "city": "Brooklyn", "age": 20, "gender": "Female", "summary": "University of Iowa student Mollie Tibbetts vanished while jogging in Brooklyn, Iowa. Cristhian Bahena Rivera was convicted of murder. Surveillance footage showed his car following her.", "lastSeen": "July 18, 2018, jogging in Brooklyn, Poweshiek County, Iowa", "tags": ["homicide", "Iowa", "2010s", "solved"], "sources": [{"title": "Murder of Mollie Tibbetts - Wikipedia", "url": "https://en.wikipedia.org/wiki/Murder_of_Mollie_Tibbetts"}, {"title": "Tibbetts case - Des Moines Register", "url": "https://www.desmoinesregister.com/story/news/investigations/mollie-tibbetts/"}, {"title": "Bahena Rivera conviction - CNN", "url": "https://www.cnn.com/2021/05/28/us/mollie-tibbetts-trial-verdict/index.html"}], "narrative": ["On July 18, 2018, Mollie Tibbetts, a 20-year-old University of Iowa student, went jogging in Brooklyn, Iowa and never returned. Her disappearance sparked a massive search.", "Surveillance footage from a neighboring property showed a dark Chevy Malibu following Mollie during her run. The car was traced to Cristhian Bahena Rivera, a farmworker.", "Bahena Rivera led investigators to Mollie's body, which was hidden in a cornfield. He initially claimed he blacked out and couldn't remember what happened.", "He was convicted of first-degree murder in 2021. The case became politically charged due to Bahena Rivera's immigration status."], "timeline": [{"date": "2018-07-18", "event": "Mollie Tibbetts disappears while jogging."}, {"date": "2021-05-28", "event": "Bahena Rivera convicted of first-degree murder."}], "enriched": True},
    {"id": "jayme-closs-2018", "name": "Jayme Closs (rescue)", "type": "Kidnapping", "status": "Solved", "year": 2019, "date": "January 10, 2019", "state": "Wisconsin", "city": "Gordon", "age": 13, "gender": "Female", "summary": "Thirteen-year-old Jayme Closs escaped after 88 days of captivity in Gordon, Wisconsin. Jake Patterson had murdered her parents and abducted her. He was sentenced to life without parole.", "lastSeen": "October 15, 2018 - January 10, 2019, Gordon, Douglas County, Wisconsin", "tags": ["kidnapping", "Wisconsin", "2010s", "solved"], "sources": [{"title": "Kidnapping of Jayme Closs - Wikipedia", "url": "https://en.wikipedia.org/wiki/Kidnapping_of_Jayme_Closs"}, {"title": "Closs escape - Minneapolis Star Tribune", "url": "https://www.startribune.com/jayme-closs/"}, {"title": "Patterson sentencing - CNN", "url": "https://www.cnn.com/2019/05/24/us/jake-patterson-jayme-closs-sentencing/index.html"}], "narrative": ["On October 15, 2018, James and Denise Closs were shot and killed in their home in Barron, Wisconsin. Their 13-year-old daughter Jayme was missing.", "Jake Patterson, 21, had targeted the Closs home after seeing Jayme getting off a school bus. He broke in with a shotgun, killed both parents, and took Jayme to his remote cabin in Gordon, Wisconsin.", "Patterson kept Jayme hidden under a bed for 88 days, threatening her and restricting her movements. On January 10, 2019, Jayme escaped while Patterson was away and flagged down a dog walker.", "Patterson was arrested within minutes. He confessed to everything and was sentenced to two consecutive life terms without parole plus 40 years. Jayme received widespread praise for her courage."], "timeline": [{"date": "2018-10-15", "event": "James and Denise Closs murdered; Jayme kidnapped."}, {"date": "2019-01-10", "event": "Jayme escapes after 88 days."}, {"date": "2019-05-24", "event": "Patterson sentenced to life without parole."}], "enriched": True},
    {"id": "darlie-routier-1996", "name": "Darlie Routier (case)", "type": "Homicide", "status": "Solved", "year": 1996, "date": "June 6, 1996", "state": "Texas", "city": "Rowlett", "age": None, "gender": "Male", "summary": "Darlie Routier was convicted of murdering her two sons in Rowlett, Texas. She claimed an intruder attacked the family. Her case remains controversial, with supporters claiming she is innocent.", "lastSeen": "June 6, 1996, their home in Rowlett, Dallas County, Texas", "tags": ["homicide", "Texas", "1990s", "controversial", "solved"], "sources": [{"title": "Darlie Routier - Wikipedia", "url": "https://en.wikipedia.org/wiki/Darlie_Routier"}, {"title": "Routier case - Dallas Morning News", "url": "https://www.dallasnews.com/news/crime/darlie-routier/"}, {"title": "Innocence debate - ABC 20/20", "url": "https://abcnews.go.com/2020/darlie-routier/"}], "narrative": ["On June 6, 1996, Darlie Routier called 911 saying an intruder had broken into her Rowlett, Texas home and stabbed her and her two sons, Damon (5) and Devon (6), while they slept downstairs.", "Both boys died. Darlie survived with injuries including a slash to her throat that narrowly missed her carotid artery. A window screen had been cut.", "Prosecutors argued Darlie staged the scene and killed her own children, pointing to blood evidence patterns, a bloody footprint, and her demeanor—including a controversial video of her spraying Silly String at the boys' grave.", "Darlie was convicted of capital murder and sentenced to death. She has maintained her innocence. Her case has attracted significant support from those who believe the evidence was mishandled and that an intruder was responsible."], "timeline": [{"date": "1996-06-06", "event": "Damon and Devon Routier murdered."}, {"date": "1997-02-04", "event": "Darlie Routier convicted; sentenced to death."}], "enriched": True},
    {"id": "scott-peterson-new-trial-2024", "name": "Scott Peterson (new evidence)", "type": "Homicide", "status": "Solved", "year": 2024, "date": "2024", "state": "California", "city": "Modesto", "age": None, "gender": "Female", "summary": "The Los Angeles Innocence Project took on Scott Peterson's case, arguing new evidence could prove his innocence. In 2024, a judge ordered new DNA testing on evidence from the Laci Peterson murder.", "lastSeen": "December 24, 2002, Modesto, Stanislaus County, California", "tags": ["homicide", "California", "2020s", "solved"], "sources": [{"title": "Scott Peterson case update - Wikipedia", "url": "https://en.wikipedia.org/wiki/Scott_Peterson"}, {"title": "Innocence Project - San Francisco Chronicle", "url": "https://www.sfchronicle.com/scott-peterson-innocence/"}, {"title": "DNA testing ordered - NBC", "url": "https://www.nbcnews.com/news/crime-courts/scott-peterson-dna-testing/"}], "narrative": ["In 2024, the Los Angeles Innocence Project filed a habeas petition on behalf of Scott Peterson, arguing that new evidence could prove he did not murder his pregnant wife Laci in 2002.", "The petition cited several pieces of evidence including a van seen near the Petersons' home that was never investigated, break-ins in the neighborhood around the time of Laci's disappearance, and potential alibi witnesses.", "A San Mateo County judge ordered new DNA testing on several items of evidence, including duct tape found on Laci's body and a mattress protector found near where her remains washed ashore.", "Peterson remains in prison serving life without parole. His death sentence was overturned in 2020 due to juror misconduct, but his murder conviction was upheld. The DNA testing results could impact his case."], "timeline": [{"date": "2002-12-24", "event": "Laci Peterson disappears."}, {"date": "2024-01-01", "event": "Judge orders new DNA testing."}], "enriched": True},
    {"id": "daniel-holtzclaw-2015", "name": "Daniel Holtzclaw Victims", "type": "Serial Rape", "status": "Solved", "year": 2015, "date": "December 10, 2015", "state": "Oklahoma", "city": "Oklahoma City", "age": 29, "gender": "Male", "summary": "Oklahoma City police officer Daniel Holtzclaw was convicted of raping and sexually assaulting 13 women while on duty. He targeted Black women in a low-income neighborhood.", "lastSeen": "Various dates, Oklahoma City, Oklahoma", "tags": ["serial rape", "Oklahoma", "2010s", "police", "solved"], "sources": [{"title": "Daniel Holtzclaw - Wikipedia", "url": "https://en.wikipedia.org/wiki/Daniel_Holtzclaw"}, {"title": "Holtzclaw trial - The Oklahoman", "url": "https://www.oklahoman.com/story/news/crime/daniel-holtzclaw/"}, {"title": "Holtzclaw case - BuzzFeed News", "url": "https://www.buzzfeednews.com/article/albertsamaha/daniel-holtzclaw"}], "narrative": ["Daniel Holtzclaw, an Oklahoma City police officer, was convicted in December 2015 of raping and sexually assaulting 13 women while on duty. His victims ranged in age from 17 to 57.", "Holtzclaw specifically targeted Black women in a low-income northeast Oklahoma City neighborhood, stopping them on pretextual traffic violations and forcing sexual acts. He chose victims he believed would not be credible witnesses.", "His downfall began when he assaulted a 57-year-old grandmother who immediately reported the attack. GPS data from his patrol car corroborated victims' accounts.", "Holtzclaw was found guilty of 18 counts including rape and sexual battery. He was sentenced to 263 years in prison. The verdict was delivered on his 29th birthday."], "timeline": [{"date": "2014-08-22", "event": "Holtzclaw arrested after final victim reports."}, {"date": "2015-12-10", "event": "Convicted on 18 counts; sentenced to 263 years."}], "enriched": True},
